BEGIN;

CREATE TABLE public.dg_company_calendar_settings(company_location text PRIMARY KEY,region_code text NOT NULL DEFAULT 'CA-BC',updated_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),updated_by_user_id uuid NULL REFERENCES auth.users(id),CHECK(company_location=pg_catalog.btrim(company_location)AND company_location<>''),CHECK(region_code=pg_catalog.btrim(region_code)AND region_code<>''));
INSERT INTO public.dg_company_calendar_settings(company_location)SELECT DISTINCT COALESCE(NULLIF(pg_catalog.btrim(company_location),''),'default')FROM public.dg_user_profiles WHERE active ON CONFLICT DO NOTHING;
CREATE TABLE public.dg_capacity_closures(closure_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),company_location text NOT NULL,start_date date NOT NULL,end_date date NOT NULL,title text NOT NULL,details text NULL,revision bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),created_by_user_id uuid NOT NULL REFERENCES auth.users(id),updated_by_user_id uuid NOT NULL REFERENCES auth.users(id),deleted_at timestamptz NULL,deleted_by_user_id uuid NULL REFERENCES auth.users(id),CHECK(end_date>=start_date AND end_date-start_date<=366),CHECK(title=pg_catalog.btrim(title)AND title<>''));
CREATE INDEX dg_capacity_closures_range_idx ON public.dg_capacity_closures(company_location,start_date,end_date)WHERE deleted_at IS NULL;
CREATE TABLE public.dg_special_days(special_day_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),company_location text NOT NULL,special_date date NOT NULL,title text NOT NULL,details text NULL,revision bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),created_by_user_id uuid NOT NULL REFERENCES auth.users(id),updated_by_user_id uuid NOT NULL REFERENCES auth.users(id),deleted_at timestamptz NULL,deleted_by_user_id uuid NULL REFERENCES auth.users(id),CHECK(title=pg_catalog.btrim(title)AND title<>''));
CREATE UNIQUE INDEX dg_special_days_date_active_idx ON public.dg_special_days(company_location,special_date)WHERE deleted_at IS NULL;
CREATE TABLE public.dg_special_day_staff(special_day_id uuid NOT NULL REFERENCES public.dg_special_days(special_day_id)ON DELETE CASCADE,staff_id uuid NOT NULL REFERENCES public.dg_capacity_staff(staff_id)ON DELETE RESTRICT,scheduled_hours numeric(6,2)NOT NULL CHECK(scheduled_hours BETWEEN 0 AND 24),productive_hours numeric(6,2)NOT NULL CHECK(productive_hours BETWEEN 0 AND 24 AND productive_hours<=scheduled_hours),PRIMARY KEY(special_day_id,staff_id));
CREATE TABLE public.dg_regional_holiday_settings(company_location text NOT NULL,holiday_year integer NOT NULL CHECK(holiday_year BETWEEN 2000 AND 2200),holiday_key text NOT NULL,enabled boolean NOT NULL,updated_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),updated_by_user_id uuid NOT NULL REFERENCES auth.users(id),PRIMARY KEY(company_location,holiday_year,holiday_key));
CREATE TABLE public.dg_capacity_overrides(company_location text NOT NULL,override_date date NOT NULL,override_capacity numeric(8,2)NOT NULL CHECK(override_capacity BETWEEN 0 AND 999),reason text NULL,revision bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp(),created_by_user_id uuid NOT NULL REFERENCES auth.users(id),updated_by_user_id uuid NOT NULL REFERENCES auth.users(id),PRIMARY KEY(company_location,override_date));
CREATE TABLE public.dg_capacity_exception_events(event_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),command_id uuid NOT NULL UNIQUE,company_location text NOT NULL,entity_type text NOT NULL CHECK(entity_type IN('closure','special_day','holiday','override')),entity_key text NOT NULL,action_type text NOT NULL CHECK(action_type IN('create','edit','delete','toggle','clear')),previous_values jsonb NULL,new_values jsonb NULL,actor_user_id uuid NOT NULL REFERENCES auth.users(id),occurred_at timestamptz NOT NULL DEFAULT pg_catalog.clock_timestamp());
CREATE INDEX dg_capacity_exception_events_entity_idx ON public.dg_capacity_exception_events(company_location,entity_type,entity_key,occurred_at DESC);

ALTER TABLE public.dg_company_calendar_settings ENABLE ROW LEVEL SECURITY;ALTER TABLE public.dg_capacity_closures ENABLE ROW LEVEL SECURITY;ALTER TABLE public.dg_special_days ENABLE ROW LEVEL SECURITY;ALTER TABLE public.dg_special_day_staff ENABLE ROW LEVEL SECURITY;ALTER TABLE public.dg_regional_holiday_settings ENABLE ROW LEVEL SECURITY;ALTER TABLE public.dg_capacity_overrides ENABLE ROW LEVEL SECURITY;ALTER TABLE public.dg_capacity_exception_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.dg_company_calendar_settings,public.dg_capacity_closures,public.dg_special_days,public.dg_special_day_staff,public.dg_regional_holiday_settings,public.dg_capacity_overrides,public.dg_capacity_exception_events FROM anon,authenticated;
CREATE POLICY dg_company_calendar_settings_read ON public.dg_company_calendar_settings FOR SELECT TO authenticated USING(company_location=public.dg_settings_scope(false));
CREATE POLICY dg_capacity_closures_read ON public.dg_capacity_closures FOR SELECT TO authenticated USING(company_location=public.dg_settings_scope(false));
CREATE POLICY dg_special_days_read ON public.dg_special_days FOR SELECT TO authenticated USING(company_location=public.dg_settings_scope(false));
CREATE POLICY dg_special_day_staff_read ON public.dg_special_day_staff FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.dg_special_days d WHERE d.special_day_id=dg_special_day_staff.special_day_id AND d.company_location=public.dg_settings_scope(false)));
CREATE POLICY dg_regional_holiday_settings_read ON public.dg_regional_holiday_settings FOR SELECT TO authenticated USING(company_location=public.dg_settings_scope(false));
CREATE POLICY dg_capacity_overrides_read ON public.dg_capacity_overrides FOR SELECT TO authenticated USING(company_location=public.dg_settings_scope(false));
CREATE POLICY dg_capacity_exception_events_read ON public.dg_capacity_exception_events FOR SELECT TO authenticated USING(company_location=public.dg_settings_scope(false));
GRANT SELECT ON public.dg_company_calendar_settings,public.dg_capacity_closures,public.dg_special_days,public.dg_special_day_staff,public.dg_regional_holiday_settings,public.dg_capacity_overrides,public.dg_capacity_exception_events TO authenticated;

CREATE OR REPLACE FUNCTION public.dg_calendar_exception_scope()RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path='' STABLE AS $$DECLARE v_actor uuid:=auth.uid();v_location text;BEGIN IF v_actor IS NULL THEN RAISE EXCEPTION USING MESSAGE='capacity_exception.authentication_required';END IF;SELECT COALESCE(NULLIF(pg_catalog.btrim(p.company_location),''),'default')INTO v_location FROM public.dg_user_profiles p WHERE p.user_id=v_actor AND p.active;IF v_location IS NULL OR NOT EXISTS(SELECT 1 FROM public.dg_user_permissions p WHERE p.user_id=v_actor AND p.permission_key='calendar'AND p.access_level IN('view','use'))THEN RAISE EXCEPTION USING MESSAGE='capacity_exception.permission_required';END IF;RETURN v_location;END$$;
CREATE OR REPLACE FUNCTION public.dg_gregorian_easter(p_year integer)RETURNS date LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$DECLARE a integer;b integer;c integer;d integer;e integer;f integer;g integer;h integer;i integer;k integer;l integer;m integer;month integer;day integer;BEGIN a:=p_year%19;b:=p_year/100;c:=p_year%100;d:=b/4;e:=b%4;f:=(b+8)/25;g:=(b-f+1)/3;h:=(19*a+b-d-g+15)%30;i:=c/4;k:=c%4;l:=(32+2*e+2*i-h-k)%7;m:=(a+11*h+22*l)/451;month:=(h+l-7*m+114)/31;day:=((h+l-7*m+114)%31)+1;RETURN pg_catalog.make_date(p_year,month,day);END$$;
CREATE OR REPLACE FUNCTION public.dg_regional_holiday_candidates(p_region text,p_year integer)RETURNS TABLE(holiday_key text,holiday_name text,holiday_date date)LANGUAGE sql IMMUTABLE SET search_path='' AS $$
WITH dates AS(SELECT pg_catalog.make_date(p_year,1,1)new_year,pg_catalog.make_date(p_year,2,1)feb,public.dg_gregorian_easter(p_year)easter,pg_catalog.make_date(p_year,5,24)may24,pg_catalog.make_date(p_year,7,1)july1,pg_catalog.make_date(p_year,8,1)aug,pg_catalog.make_date(p_year,9,1)sep,pg_catalog.make_date(p_year,9,30)truth,pg_catalog.make_date(p_year,10,1)oct,pg_catalog.make_date(p_year,11,11)remembrance,pg_catalog.make_date(p_year,12,25)christmas)
SELECT v.key,v.name,v.day FROM dates d CROSS JOIN LATERAL(VALUES('new_year','New Year''s Day',d.new_year),('family_day','Family Day',d.feb+((8-EXTRACT(DOW FROM d.feb)::integer)%7+14)),('good_friday','Good Friday',d.easter-2),('victoria_day','Victoria Day',d.may24-((EXTRACT(DOW FROM d.may24)::integer+6)%7)),('canada_day','Canada Day',CASE WHEN EXTRACT(DOW FROM d.july1)=0 THEN d.july1+1 ELSE d.july1 END),('bc_day','B.C. Day',d.aug+((8-EXTRACT(DOW FROM d.aug)::integer)%7)),('labour_day','Labour Day',d.sep+((8-EXTRACT(DOW FROM d.sep)::integer)%7)),('truth_reconciliation','National Day for Truth and Reconciliation',d.truth),('thanksgiving','Thanksgiving Day',d.oct+((8-EXTRACT(DOW FROM d.oct)::integer)%7+7)),('remembrance','Remembrance Day',d.remembrance),('christmas','Christmas Day',d.christmas))v(key,name,day)WHERE p_region='CA-BC'$$;

CREATE OR REPLACE FUNCTION public.dg_capacity_exception_is_closed(p_location text,p_date date)RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path='' STABLE AS $$SELECT EXISTS(SELECT 1 FROM public.dg_capacity_closures c WHERE c.company_location=p_location AND c.deleted_at IS NULL AND p_date BETWEEN c.start_date AND c.end_date)OR EXISTS(SELECT 1 FROM public.dg_company_calendar_settings s CROSS JOIN LATERAL public.dg_regional_holiday_candidates(s.region_code,EXTRACT(YEAR FROM p_date)::integer)h WHERE s.company_location=p_location AND h.holiday_date=p_date AND COALESCE((SELECT x.enabled FROM public.dg_regional_holiday_settings x WHERE x.company_location=p_location AND x.holiday_year=EXTRACT(YEAR FROM p_date)::integer AND x.holiday_key=h.holiday_key),true))$$;
CREATE OR REPLACE FUNCTION public.dg_special_day_capacity(p_location text,p_date date)RETURNS numeric LANGUAGE sql SECURITY DEFINER SET search_path='' STABLE AS $$SELECT COALESCE(pg_catalog.sum(s.productive_hours),0)FROM public.dg_special_days d LEFT JOIN public.dg_special_day_staff s ON s.special_day_id=d.special_day_id WHERE d.company_location=p_location AND d.special_date=p_date AND d.deleted_at IS NULL GROUP BY d.special_day_id$$;
CREATE OR REPLACE FUNCTION public.dg_capacity_override_value(p_location text,p_date date)RETURNS numeric LANGUAGE sql SECURITY DEFINER SET search_path='' STABLE AS $$SELECT o.override_capacity FROM public.dg_capacity_overrides o WHERE o.company_location=p_location AND o.override_date=p_date$$;

CREATE OR REPLACE FUNCTION public.dg_recalculate_capacity_exception_date(p_location text,p_date date)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r public.dg_daily_capacity%ROWTYPE;base_available numeric;base_deduction numeric;away numeric;special numeric;override_value numeric;closed boolean;created boolean:=false;BEGIN
 SELECT * INTO r FROM public.dg_daily_capacity WHERE production_date=p_date FOR UPDATE;special:=public.dg_special_day_capacity(p_location,p_date);override_value:=public.dg_capacity_override_value(p_location,p_date);closed:=public.dg_capacity_exception_is_closed(p_location,p_date);
 IF NOT FOUND THEN IF special IS NULL AND override_value IS NULL THEN RETURN;END IF;PERFORM pg_catalog.set_config('doorgo.capacity_exception_recalc','1',true);INSERT INTO public.dg_daily_capacity(production_date,available_hours,staff_capacity_hours,deduction_hours,capacity_source,is_closed,notes,details,source_system,calculated_at)VALUES(p_date,NULL,NULL,0,'unknown',false,NULL,pg_catalog.jsonb_build_object('native_capacity_created_for_exception',true),'native-manager-exception',pg_catalog.clock_timestamp());SELECT * INTO r FROM public.dg_daily_capacity WHERE production_date=p_date FOR UPDATE;created:=true;END IF;
 base_available:=CASE WHEN COALESCE((r.details->>'native_capacity_layers_applied')::boolean,false)THEN (r.details->>'native_capacity_bridge_available_hours')::numeric WHEN COALESCE((r.details->>'native_staff_away_applied')::boolean,false)THEN (r.details->>'native_staff_away_baseline_available_hours')::numeric WHEN r.capacity_source='closure'AND NULLIF(r.details->>'calculated_available_hours','')IS NOT NULL THEN(r.details->>'calculated_available_hours')::numeric ELSE r.available_hours END;
 base_deduction:=CASE WHEN COALESCE((r.details->>'native_capacity_layers_applied')::boolean,false)THEN COALESCE((r.details->>'native_capacity_bridge_deduction_hours')::numeric,0)WHEN COALESCE((r.details->>'native_staff_away_applied')::boolean,false)THEN COALESCE((r.details->>'native_staff_away_baseline_deduction_hours')::numeric,0)ELSE COALESCE(r.deduction_hours,0)END;away:=public.dg_staff_away_deduction(p_location,p_date);
 IF special IS NULL AND override_value IS NULL AND NOT closed AND COALESCE((r.details->>'native_capacity_created_for_exception')::boolean,false)THEN DELETE FROM public.dg_daily_capacity WHERE production_date=p_date;RETURN;END IF;
 PERFORM pg_catalog.set_config('doorgo.capacity_exception_recalc','1',true);UPDATE public.dg_daily_capacity SET available_hours=CASE WHEN override_value IS NOT NULL THEN override_value WHEN closed THEN 0 WHEN special IS NOT NULL THEN special WHEN base_available IS NULL THEN NULL ELSE GREATEST(0::numeric,base_available-away)END,staff_capacity_hours=CASE WHEN special IS NOT NULL THEN special ELSE r.staff_capacity_hours END,deduction_hours=CASE WHEN special IS NOT NULL THEN base_deduction ELSE base_deduction+away END,capacity_source=CASE WHEN override_value IS NOT NULL THEN'override'WHEN closed THEN'closure'WHEN base_available IS NULL AND special IS NULL THEN'unknown'ELSE'calculated'END,is_closed=closed AND override_value IS NULL,notes=COALESCE((SELECT o.reason FROM public.dg_capacity_overrides o WHERE o.company_location=p_location AND o.override_date=p_date),r.notes),details=COALESCE(r.details,'{}'::jsonb)||pg_catalog.jsonb_build_object('native_capacity_layers_applied',true,'native_capacity_bridge_available_hours',base_available,'native_capacity_bridge_deduction_hours',base_deduction,'native_staff_away_deduction_hours',away,'native_special_day_capacity',special,'native_capacity_closed',closed,'native_capacity_override',override_value),updated_at=pg_catalog.clock_timestamp()WHERE production_date=p_date;END$$;
CREATE OR REPLACE FUNCTION public.dg_recalculate_capacity_exception_range(p_location text,p_start date,p_end date)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE d date;BEGIN IF p_end<p_start OR p_end-p_start>366 THEN RAISE EXCEPTION USING MESSAGE='capacity_exception.invalid_range';END IF;FOR d IN SELECT x::date FROM pg_catalog.generate_series(p_start,p_end,'1 day'::interval)x LOOP PERFORM public.dg_recalculate_capacity_exception_date(p_location,d);END LOOP;END$$;

CREATE OR REPLACE FUNCTION public.dg_apply_staff_away_to_capacity_row()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE location text;away numeric;special numeric;override_value numeric;closed boolean;base_available numeric:=NEW.available_hours;base_deduction numeric:=COALESCE(NEW.deduction_hours,0);BEGIN IF pg_catalog.current_setting('doorgo.capacity_exception_recalc',true)='1'OR pg_catalog.current_setting('doorgo.staff_away_recalc',true)='1'THEN RETURN NEW;END IF;SELECT COALESCE(NULLIF(pg_catalog.btrim(p.company_location),''),'default')INTO location FROM public.dg_user_profiles p WHERE p.active ORDER BY p.created_at LIMIT 1;IF location IS NULL THEN RETURN NEW;END IF;away:=public.dg_staff_away_deduction(location,NEW.production_date);special:=public.dg_special_day_capacity(location,NEW.production_date);override_value:=public.dg_capacity_override_value(location,NEW.production_date);closed:=public.dg_capacity_exception_is_closed(location,NEW.production_date);NEW.available_hours:=CASE WHEN override_value IS NOT NULL THEN override_value WHEN closed THEN 0 WHEN special IS NOT NULL THEN special WHEN base_available IS NULL THEN NULL ELSE GREATEST(0::numeric,base_available-away)END;NEW.staff_capacity_hours:=CASE WHEN special IS NOT NULL THEN special ELSE NEW.staff_capacity_hours END;NEW.deduction_hours:=CASE WHEN special IS NOT NULL THEN base_deduction ELSE base_deduction+away END;NEW.capacity_source:=CASE WHEN override_value IS NOT NULL THEN'override'WHEN closed THEN'closure'WHEN base_available IS NULL AND special IS NULL THEN'unknown'ELSE'calculated'END;NEW.is_closed:=closed AND override_value IS NULL;NEW.details:=COALESCE(NEW.details,'{}'::jsonb)||pg_catalog.jsonb_build_object('native_capacity_layers_applied',true,'native_capacity_bridge_available_hours',base_available,'native_capacity_bridge_deduction_hours',base_deduction,'native_staff_away_deduction_hours',away,'native_special_day_capacity',special,'native_capacity_closed',closed,'native_capacity_override',override_value);RETURN NEW;END$$;
CREATE OR REPLACE FUNCTION public.dg_recalculate_staff_away_capacity(p_location text,p_start date,p_end date)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN PERFORM public.dg_recalculate_capacity_exception_range(p_location,p_start,p_end);END$$;

CREATE OR REPLACE FUNCTION public.load_manager_capacity_exceptions(p_year integer)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' STABLE AS $$DECLARE location text:=public.dg_settings_scope(false);region text;BEGIN IF p_year NOT BETWEEN 2000 AND 2200 THEN RAISE EXCEPTION USING MESSAGE='capacity_exception.invalid_year';END IF;SELECT COALESCE(s.region_code,'CA-BC')INTO region FROM public.dg_company_calendar_settings s WHERE s.company_location=location;region:=COALESCE(region,'CA-BC');RETURN pg_catalog.jsonb_build_object('regionCode',region,'year',p_year,'closures',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('closureId',c.closure_id,'startDate',c.start_date,'endDate',c.end_date,'title',c.title,'details',c.details,'revision',c.revision)ORDER BY c.start_date,c.title)FROM public.dg_capacity_closures c WHERE c.company_location=location AND c.deleted_at IS NULL AND c.end_date>=pg_catalog.make_date(p_year,1,1)AND c.start_date<pg_catalog.make_date(p_year+1,1,1)),'[]'::jsonb),'specialDays',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('specialDayId',d.special_day_id,'date',d.special_date,'title',d.title,'details',d.details,'revision',d.revision,'calculatedCapacity',COALESCE((SELECT pg_catalog.sum(x.productive_hours)FROM public.dg_special_day_staff x WHERE x.special_day_id=d.special_day_id),0),'staff',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('staffId',x.staff_id,'displayName',s.display_name,'scheduledHours',x.scheduled_hours,'productiveHours',x.productive_hours)ORDER BY s.display_name)FROM public.dg_special_day_staff x JOIN public.dg_capacity_staff s ON s.staff_id=x.staff_id WHERE x.special_day_id=d.special_day_id),'[]'::jsonb))ORDER BY d.special_date,d.title)FROM public.dg_special_days d WHERE d.company_location=location AND d.deleted_at IS NULL AND EXTRACT(YEAR FROM d.special_date)=p_year),'[]'::jsonb),'holidays',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('holidayKey',h.holiday_key,'name',h.holiday_name,'date',h.holiday_date,'enabled',COALESCE(s.enabled,true))ORDER BY h.holiday_date)FROM public.dg_regional_holiday_candidates(region,p_year)h LEFT JOIN public.dg_regional_holiday_settings s ON s.company_location=location AND s.holiday_year=p_year AND s.holiday_key=h.holiday_key),'[]'::jsonb),'overrides',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('date',o.override_date,'overrideCapacity',o.override_capacity,'reason',o.reason,'revision',o.revision,'calculatedCapacity',(c.details->>'native_capacity_bridge_available_hours')::numeric)ORDER BY o.override_date)FROM public.dg_capacity_overrides o LEFT JOIN public.dg_daily_capacity c ON c.production_date=o.override_date WHERE o.company_location=location AND EXTRACT(YEAR FROM o.override_date)=p_year),'[]'::jsonb));END$$;

CREATE OR REPLACE FUNCTION public.load_capacity_exceptions_calendar_range(p_start date,p_end_exclusive date)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' STABLE AS $$DECLARE location text:=public.dg_calendar_exception_scope();region text;BEGIN IF p_start IS NULL OR p_end_exclusive<=p_start OR p_end_exclusive-p_start>370 THEN RAISE EXCEPTION USING MESSAGE='capacity_exception.invalid_range';END IF;SELECT COALESCE(s.region_code,'CA-BC')INTO region FROM public.dg_company_calendar_settings s WHERE s.company_location=location;region:=COALESCE(region,'CA-BC');RETURN pg_catalog.jsonb_build_object('records',COALESCE((SELECT pg_catalog.jsonb_agg(record ORDER BY record->>'startDate',record->>'title')FROM(SELECT pg_catalog.jsonb_build_object('recordId',c.closure_id,'kind','closure','title',c.title,'details',c.details,'startDate',c.start_date,'endDate',c.end_date,'revision',c.revision,'capacityHours',0,'staffNames','[]'::jsonb,'occurrences',(SELECT pg_catalog.jsonb_agg(x::date ORDER BY x)FROM pg_catalog.generate_series(GREATEST(c.start_date,p_start),LEAST(c.end_date,p_end_exclusive-1),'1 day'::interval)x))record FROM public.dg_capacity_closures c WHERE c.company_location=location AND c.deleted_at IS NULL AND c.end_date>=p_start AND c.start_date<p_end_exclusive UNION ALL SELECT pg_catalog.jsonb_build_object('recordId',d.special_day_id,'kind','special_day','title',d.title,'details',d.details,'startDate',d.special_date,'endDate',d.special_date,'revision',d.revision,'capacityHours',COALESCE((SELECT pg_catalog.sum(x.productive_hours)FROM public.dg_special_day_staff x WHERE x.special_day_id=d.special_day_id),0),'staffNames',COALESCE((SELECT pg_catalog.jsonb_agg(s.display_name ORDER BY s.display_name)FROM public.dg_special_day_staff x JOIN public.dg_capacity_staff s ON s.staff_id=x.staff_id WHERE x.special_day_id=d.special_day_id),'[]'::jsonb),'occurrences',pg_catalog.jsonb_build_array(d.special_date))FROM public.dg_special_days d WHERE d.company_location=location AND d.deleted_at IS NULL AND d.special_date>=p_start AND d.special_date<p_end_exclusive UNION ALL SELECT pg_catalog.jsonb_build_object('recordId',h.holiday_key||':'||EXTRACT(YEAR FROM h.holiday_date)::integer,'kind','holiday','title',h.holiday_name,'details',NULL,'startDate',h.holiday_date,'endDate',h.holiday_date,'revision',1,'capacityHours',0,'staffNames','[]'::jsonb,'occurrences',pg_catalog.jsonb_build_array(h.holiday_date))FROM pg_catalog.generate_series(EXTRACT(YEAR FROM p_start)::integer,EXTRACT(YEAR FROM p_end_exclusive-1)::integer)y CROSS JOIN LATERAL public.dg_regional_holiday_candidates(region,y)h LEFT JOIN public.dg_regional_holiday_settings s ON s.company_location=location AND s.holiday_year=y AND s.holiday_key=h.holiday_key WHERE h.holiday_date>=p_start AND h.holiday_date<p_end_exclusive AND COALESCE(s.enabled,true))q),'[]'::jsonb),'exceptionalDates',COALESCE((SELECT pg_catalog.jsonb_agg(d.special_date ORDER BY d.special_date)FROM public.dg_special_days d WHERE d.company_location=location AND d.deleted_at IS NULL AND d.special_date>=p_start AND d.special_date<p_end_exclusive AND EXTRACT(DOW FROM d.special_date)IN(0,6)),'[]'::jsonb));END$$;

CREATE OR REPLACE FUNCTION public.save_capacity_closure(p_command_id uuid,p_closure_id uuid,p_expected_revision bigint,p_start_date date,p_end_date date,p_title text,p_details text)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE actor uuid:=auth.uid();location text:=public.dg_settings_scope(true);id uuid:=COALESCE(p_closure_id,extensions.gen_random_uuid());old public.dg_capacity_closures%ROWTYPE;BEGIN IF p_command_id IS NULL OR p_start_date IS NULL OR p_end_date<p_start_date OR p_end_date-p_start_date>366 OR NULLIF(pg_catalog.btrim(p_title),'')IS NULL THEN RAISE EXCEPTION USING MESSAGE='capacity_exception.invalid_closure';END IF;IF EXISTS(SELECT 1 FROM public.dg_capacity_exception_events WHERE command_id=p_command_id)THEN RETURN id;END IF;IF p_closure_id IS NULL THEN INSERT INTO public.dg_capacity_closures(closure_id,company_location,start_date,end_date,title,details,created_by_user_id,updated_by_user_id)VALUES(id,location,p_start_date,p_end_date,pg_catalog.btrim(p_title),NULLIF(pg_catalog.btrim(p_details),''),actor,actor);ELSE SELECT*INTO old FROM public.dg_capacity_closures WHERE closure_id=id AND company_location=location AND deleted_at IS NULL FOR UPDATE;IF NOT FOUND OR old.revision<>p_expected_revision THEN RAISE EXCEPTION USING MESSAGE='capacity_exception.stale_closure';END IF;UPDATE public.dg_capacity_closures SET start_date=p_start_date,end_date=p_end_date,title=pg_catalog.btrim(p_title),details=NULLIF(pg_catalog.btrim(p_details),''),revision=revision+1,updated_at=pg_catalog.clock_timestamp(),updated_by_user_id=actor WHERE closure_id=id;PERFORM public.dg_recalculate_capacity_exception_range(location,old.start_date,old.end_date);END IF;INSERT INTO public.dg_capacity_exception_events(command_id,company_location,entity_type,entity_key,action_type,previous_values,new_values,actor_user_id)VALUES(p_command_id,location,'closure',id::text,CASE WHEN p_closure_id IS NULL THEN'create'ELSE'edit'END,CASE WHEN p_closure_id IS NULL THEN NULL ELSE pg_catalog.to_jsonb(old)END,pg_catalog.jsonb_build_object('startDate',p_start_date,'endDate',p_end_date,'title',p_title),actor);PERFORM public.dg_recalculate_capacity_exception_range(location,p_start_date,p_end_date);RETURN id;END$$;
CREATE OR REPLACE FUNCTION public.delete_capacity_closure(p_command_id uuid,p_closure_id uuid,p_expected_revision bigint)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE actor uuid:=auth.uid();location text:=public.dg_settings_scope(true);old public.dg_capacity_closures%ROWTYPE;BEGIN SELECT*INTO old FROM public.dg_capacity_closures WHERE closure_id=p_closure_id AND company_location=location AND deleted_at IS NULL FOR UPDATE;IF NOT FOUND OR old.revision<>p_expected_revision THEN RAISE EXCEPTION USING MESSAGE='capacity_exception.stale_closure';END IF;UPDATE public.dg_capacity_closures SET deleted_at=pg_catalog.clock_timestamp(),deleted_by_user_id=actor,revision=revision+1,updated_at=pg_catalog.clock_timestamp(),updated_by_user_id=actor WHERE closure_id=p_closure_id;INSERT INTO public.dg_capacity_exception_events VALUES(extensions.gen_random_uuid(),p_command_id,location,'closure',p_closure_id::text,'delete',pg_catalog.to_jsonb(old),NULL,actor,pg_catalog.clock_timestamp());PERFORM public.dg_recalculate_capacity_exception_range(location,old.start_date,old.end_date);END$$;

CREATE OR REPLACE FUNCTION public.save_special_day(p_command_id uuid,p_special_day_id uuid,p_expected_revision bigint,p_date date,p_title text,p_details text,p_staff jsonb)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE actor uuid:=auth.uid();location text:=public.dg_settings_scope(true);id uuid:=COALESCE(p_special_day_id,extensions.gen_random_uuid());old public.dg_special_days%ROWTYPE;entry jsonb;BEGIN IF p_command_id IS NULL OR p_date IS NULL OR NULLIF(pg_catalog.btrim(p_title),'')IS NULL OR pg_catalog.jsonb_typeof(p_staff)<>'array'THEN RAISE EXCEPTION USING MESSAGE='capacity_exception.invalid_special_day';END IF;IF p_special_day_id IS NULL THEN INSERT INTO public.dg_special_days(special_day_id,company_location,special_date,title,details,created_by_user_id,updated_by_user_id)VALUES(id,location,p_date,pg_catalog.btrim(p_title),NULLIF(pg_catalog.btrim(p_details),''),actor,actor);ELSE SELECT*INTO old FROM public.dg_special_days WHERE special_day_id=id AND company_location=location AND deleted_at IS NULL FOR UPDATE;IF NOT FOUND OR old.revision<>p_expected_revision THEN RAISE EXCEPTION USING MESSAGE='capacity_exception.stale_special_day';END IF;UPDATE public.dg_special_days SET special_date=p_date,title=pg_catalog.btrim(p_title),details=NULLIF(pg_catalog.btrim(p_details),''),revision=revision+1,updated_at=pg_catalog.clock_timestamp(),updated_by_user_id=actor WHERE special_day_id=id;DELETE FROM public.dg_special_day_staff WHERE special_day_id=id;END IF;FOR entry IN SELECT value FROM pg_catalog.jsonb_array_elements(p_staff)LOOP IF NOT EXISTS(SELECT 1 FROM public.dg_capacity_staff s WHERE s.staff_id=(entry->>'staffId')::uuid AND s.company_location=location AND s.active)THEN RAISE EXCEPTION USING MESSAGE='capacity_exception.invalid_staff';END IF;INSERT INTO public.dg_special_day_staff VALUES(id,(entry->>'staffId')::uuid,(entry->>'scheduledHours')::numeric,(entry->>'productiveHours')::numeric);END LOOP;INSERT INTO public.dg_capacity_exception_events(command_id,company_location,entity_type,entity_key,action_type,previous_values,new_values,actor_user_id)VALUES(p_command_id,location,'special_day',id::text,CASE WHEN p_special_day_id IS NULL THEN'create'ELSE'edit'END,CASE WHEN p_special_day_id IS NULL THEN NULL ELSE pg_catalog.to_jsonb(old)END,pg_catalog.jsonb_build_object('date',p_date,'title',p_title,'staff',p_staff),actor);IF p_special_day_id IS NOT NULL AND old.special_date<>p_date THEN PERFORM public.dg_recalculate_capacity_exception_date(location,old.special_date);END IF;PERFORM public.dg_recalculate_capacity_exception_date(location,p_date);RETURN id;END$$;
CREATE OR REPLACE FUNCTION public.delete_special_day(p_command_id uuid,p_special_day_id uuid,p_expected_revision bigint)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE actor uuid:=auth.uid();location text:=public.dg_settings_scope(true);old public.dg_special_days%ROWTYPE;BEGIN SELECT*INTO old FROM public.dg_special_days WHERE special_day_id=p_special_day_id AND company_location=location AND deleted_at IS NULL FOR UPDATE;IF NOT FOUND OR old.revision<>p_expected_revision THEN RAISE EXCEPTION USING MESSAGE='capacity_exception.stale_special_day';END IF;UPDATE public.dg_special_days SET deleted_at=pg_catalog.clock_timestamp(),deleted_by_user_id=actor,revision=revision+1,updated_at=pg_catalog.clock_timestamp(),updated_by_user_id=actor WHERE special_day_id=p_special_day_id;INSERT INTO public.dg_capacity_exception_events VALUES(extensions.gen_random_uuid(),p_command_id,location,'special_day',p_special_day_id::text,'delete',pg_catalog.to_jsonb(old),NULL,actor,pg_catalog.clock_timestamp());PERFORM public.dg_recalculate_capacity_exception_date(location,old.special_date);END$$;

CREATE OR REPLACE FUNCTION public.set_regional_holiday_enabled(p_command_id uuid,p_year integer,p_holiday_key text,p_enabled boolean)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE actor uuid:=auth.uid();location text:=public.dg_settings_scope(true);region text;holiday_date date;BEGIN SELECT COALESCE(s.region_code,'CA-BC')INTO region FROM public.dg_company_calendar_settings s WHERE s.company_location=location;SELECT h.holiday_date INTO holiday_date FROM public.dg_regional_holiday_candidates(COALESCE(region,'CA-BC'),p_year)h WHERE h.holiday_key=p_holiday_key;IF holiday_date IS NULL THEN RAISE EXCEPTION USING MESSAGE='capacity_exception.invalid_holiday';END IF;INSERT INTO public.dg_regional_holiday_settings VALUES(location,p_year,p_holiday_key,p_enabled,pg_catalog.clock_timestamp(),actor)ON CONFLICT(company_location,holiday_year,holiday_key)DO UPDATE SET enabled=EXCLUDED.enabled,updated_at=EXCLUDED.updated_at,updated_by_user_id=EXCLUDED.updated_by_user_id;INSERT INTO public.dg_capacity_exception_events(command_id,company_location,entity_type,entity_key,action_type,new_values,actor_user_id)VALUES(p_command_id,location,'holiday',p_year||':'||p_holiday_key,'toggle',pg_catalog.jsonb_build_object('enabled',p_enabled),actor);PERFORM public.dg_recalculate_capacity_exception_date(location,holiday_date);END$$;
CREATE OR REPLACE FUNCTION public.save_capacity_override(p_command_id uuid,p_date date,p_override_capacity numeric,p_reason text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE actor uuid:=auth.uid();location text:=public.dg_settings_scope(true);old public.dg_capacity_overrides%ROWTYPE;BEGIN IF p_date IS NULL OR(p_override_capacity IS NOT NULL AND(p_override_capacity<0 OR p_override_capacity>999))THEN RAISE EXCEPTION USING MESSAGE='capacity_exception.invalid_override';END IF;SELECT*INTO old FROM public.dg_capacity_overrides WHERE company_location=location AND override_date=p_date FOR UPDATE;IF p_override_capacity IS NULL THEN DELETE FROM public.dg_capacity_overrides WHERE company_location=location AND override_date=p_date;ELSE INSERT INTO public.dg_capacity_overrides(company_location,override_date,override_capacity,reason,created_by_user_id,updated_by_user_id)VALUES(location,p_date,p_override_capacity,NULLIF(pg_catalog.btrim(p_reason),''),actor,actor)ON CONFLICT(company_location,override_date)DO UPDATE SET override_capacity=EXCLUDED.override_capacity,reason=EXCLUDED.reason,revision=public.dg_capacity_overrides.revision+1,updated_at=pg_catalog.clock_timestamp(),updated_by_user_id=actor;END IF;INSERT INTO public.dg_capacity_exception_events(command_id,company_location,entity_type,entity_key,action_type,previous_values,new_values,actor_user_id)VALUES(p_command_id,location,'override',p_date::text,CASE WHEN p_override_capacity IS NULL THEN'clear'WHEN old.override_date IS NULL THEN'create'ELSE'edit'END,CASE WHEN old.override_date IS NULL THEN NULL ELSE pg_catalog.to_jsonb(old)END,CASE WHEN p_override_capacity IS NULL THEN NULL ELSE pg_catalog.jsonb_build_object('capacity',p_override_capacity,'reason',p_reason)END,actor);PERFORM public.dg_recalculate_capacity_exception_date(location,p_date);END$$;

DO $$DECLARE f regprocedure;BEGIN FOREACH f IN ARRAY ARRAY['public.load_manager_capacity_exceptions(integer)'::regprocedure,'public.load_capacity_exceptions_calendar_range(date,date)'::regprocedure,'public.save_capacity_closure(uuid,uuid,bigint,date,date,text,text)'::regprocedure,'public.delete_capacity_closure(uuid,uuid,bigint)'::regprocedure,'public.save_special_day(uuid,uuid,bigint,date,text,text,jsonb)'::regprocedure,'public.delete_special_day(uuid,uuid,bigint)'::regprocedure,'public.set_regional_holiday_enabled(uuid,integer,text,boolean)'::regprocedure,'public.save_capacity_override(uuid,date,numeric,text)'::regprocedure]LOOP EXECUTE'ALTER FUNCTION '||f||' OWNER TO postgres';EXECUTE'REVOKE ALL ON FUNCTION '||f||' FROM PUBLIC,anon';EXECUTE'GRANT EXECUTE ON FUNCTION '||f||' TO authenticated';END LOOP;END$$;
CREATE OR REPLACE FUNCTION public.dg_apply_staff_away_to_capacity_row()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE location text;away numeric;special numeric;override_value numeric;closed boolean;
  base_available numeric:=CASE WHEN NEW.capacity_source='closure'AND NULLIF(NEW.details->>'calculated_available_hours','')IS NOT NULL THEN(NEW.details->>'calculated_available_hours')::numeric ELSE NEW.available_hours END;
  base_deduction numeric:=COALESCE(NEW.deduction_hours,0);
BEGIN
 IF pg_catalog.current_setting('doorgo.capacity_exception_recalc',true)='1'OR pg_catalog.current_setting('doorgo.staff_away_recalc',true)='1'THEN RETURN NEW;END IF;
 SELECT COALESCE(NULLIF(pg_catalog.btrim(p.company_location),''),'default')INTO location FROM public.dg_user_profiles p WHERE p.active ORDER BY p.created_at LIMIT 1;
 IF location IS NULL THEN RETURN NEW;END IF;
 away:=public.dg_staff_away_deduction(location,NEW.production_date);special:=public.dg_special_day_capacity(location,NEW.production_date);override_value:=public.dg_capacity_override_value(location,NEW.production_date);closed:=public.dg_capacity_exception_is_closed(location,NEW.production_date);
 NEW.available_hours:=CASE WHEN override_value IS NOT NULL THEN override_value WHEN closed THEN 0 WHEN special IS NOT NULL THEN special WHEN base_available IS NULL THEN NULL ELSE GREATEST(0::numeric,base_available-away)END;
 NEW.staff_capacity_hours:=CASE WHEN special IS NOT NULL THEN special ELSE NEW.staff_capacity_hours END;NEW.deduction_hours:=CASE WHEN special IS NOT NULL THEN base_deduction ELSE base_deduction+away END;NEW.capacity_source:=CASE WHEN override_value IS NOT NULL THEN'override'WHEN closed THEN'closure'WHEN base_available IS NULL AND special IS NULL THEN'unknown'ELSE'calculated'END;NEW.is_closed:=closed AND override_value IS NULL;
 NEW.details:=COALESCE(NEW.details,'{}'::jsonb)||pg_catalog.jsonb_build_object('native_capacity_layers_applied',true,'native_capacity_bridge_available_hours',base_available,'native_capacity_bridge_deduction_hours',base_deduction,'native_staff_away_deduction_hours',away,'native_special_day_capacity',special,'native_capacity_closed',closed,'native_capacity_override',override_value);RETURN NEW;
END$$;

REVOKE ALL ON FUNCTION public.dg_calendar_exception_scope(),public.dg_gregorian_easter(integer),public.dg_regional_holiday_candidates(text,integer),public.dg_capacity_exception_is_closed(text,date),public.dg_special_day_capacity(text,date),public.dg_capacity_override_value(text,date),public.dg_recalculate_capacity_exception_date(text,date),public.dg_recalculate_capacity_exception_range(text,date,date)FROM PUBLIC,anon,authenticated;
COMMIT;
